const patients=[['Амина Садуакасова','+7 701 245 18 09','Физиотерапия','Сегодня, 10:30','АС','lavender'],['Марат Тлеубаев','+7 777 331 42 20','Лазерная терапия','Сегодня, 11:20','МТ','peach'],['Елена Новикова','+7 705 880 12 43','Массаж','Сегодня, 12:00','ЕН','mint'],['Данияр Касымов','+7 702 604 33 11','Перевязка','Сегодня, 12:40','ДК','sky'],['Ольга Белова','+7 747 210 76 55','Консультация','Завтра, 09:00','ОБ','rose']];
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav-item').forEach(v=>v.classList.toggle('active',v.dataset.view===id));$('#page-title').textContent={dashboard:'Добрый день, Айжан',patients:'Пациенты',schedule:'Расписание процедур',messages:'WhatsApp-уведомления'}[id];}
$$('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));
$('#patients-table').innerHTML='<div class="data-row head"><span>ПАЦИЕНТ</span><span>ТЕЛЕФОН</span><span>ПРОЦЕДУРА</span><span>СЛЕДУЮЩИЙ ВИЗИТ</span></div>'+patients.map(p=>`<div class="data-row"><span class="person"><i class="avatar ${p[5]}">${p[4]}</i><strong>${p[0]}</strong></span><span>${p[1]}</span><span>${p[2]}</span><span>${p[3]}</span></div>`).join('');
const days=['Вт 21','Ср 22','Чт 23','Пт 24','Сб 25','Вс 26','Пн 27'];const events=[['10:30 Амина','12:00 Елена'],['09:00 Ольга','10:00 Марат'],['11:20 Данияр'],['10:00 Амина','14:30 Елена'],['09:40 Марат'],[],['11:00 Ольга']];$('#calendar').innerHTML=days.map((d,i)=>`<div class="day"><strong>${d}</strong>${events[i].map((e,j)=>`<div class="event ${j%2?'orange':''}">${e}</div>`).join('')}</div>`).join('');
$('#message-log').innerHTML=[['10:02','Амина Садуакасова','Напоминание о визите','Доставлено'],['09:48','Елена Новикова','Ответ: подтверждаю','Получено'],['09:31','Данияр Касымов','Напоминание о визите','Ожидает'],['Вчера','Ольга Белова','Запрос на перенос','Получено']].map(x=>`<div class="log-row"><span>${x[0]}</span><strong>${x[1]}</strong><span>${x[2]}</span><span class="tag ${x[3]==='Доставлено'?'confirmed':x[3]==='Ожидает'?'waiting':'process'}">${x[3]}</span></div>`).join('');
const dialog=$('#visit-dialog');['#new-visit','#new-visit-2'].forEach(s=>$(s).onclick=()=>dialog.showModal());
function updatePreview(){const d=$('#date').value.split('-').reverse().join('.');$('#preview-date').textContent=`${d} в ${$('#time').value}`;}$('#date').onchange=updatePreview;$('#time').onchange=updatePreview;
$('#save-visit').onclick=async e=>{e.preventDefault();const patientIndex=$('#patient').selectedIndex+1;const payload={patient_id:patientIndex,procedure_name:$('#procedure').value,doctor_name:dialog.querySelector('select:not(#patient)').value,starts_at:`${$('#date').value}T${$('#time').value}`,send_whatsapp:dialog.querySelector('.check input').checked};try{const response=await fetch('/api/appointments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Не удалось сохранить');dialog.close();$('#toast strong').textContent='Визит назначен';$('#toast small').textContent=result.whatsapp_queued?'WhatsApp-сообщение поставлено в очередь':'Визит сохранён без сообщения';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}catch(error){alert(error.message)}};
$$('.send-reminder').forEach(b=>b.onclick=()=>{b.textContent='Отправлено ✓';b.disabled=true;$('#toast strong').textContent='Напоминание отправлено';$('#toast small').textContent='Сообщение доставляется пациенту';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)});
$('.search').oninput=e=>{$$('#patients-table .data-row:not(.head)').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(e.target.value.toLowerCase())?'grid':'none')};

